parameters.jsonBody:
={{ JSON.stringify({
  model: "openai/gpt-oss-120b",
  max_tokens: 800,
  messages: [
    {
      role: "system",
      content: "You extract structured narrative facts from raw project notes for a LinkedIn post. Output ONLY valid JSON, no markdown fences, no preamble, no explanation before or after. Schema: {\"hook_angle\": string, \"key_facts\": [{\"fact\": string, \"status\": \"verified\"|\"unverified\"}], \"tone_notes\": string}. Mark a fact unverified if it came from the unverified_claims field or if a metric has no clear source. Never invent facts not present in the input."
    },
    {
      role: "user",
      content: `Project: ${$json.project_name}\nWhat was built: ${$json.what_built}\nTech stack: ${$json.tech_stack}\nTimeframe: ${$json.timeframe}\nTeam or solo: ${$json.team_or_solo}\nVerified metrics: ${$json.verified_metrics}\nUnverified/uncertain claims: ${$json.unverified_claims}\nPost type: ${$json.post_type}`
    }
  ]
}) }}

={{ JSON.stringify({
  model: "openai/gpt-oss-120b",
  max_tokens: 600,
  messages: [
    {
      role: "system",
      content: "You write LinkedIn posts in this exact voice: direct, decision-driven, honest about limits, no hype. No emoji-stacking, no 'thrilled to announce', no fake humility, no exclamation-point stacking. Short sentences. Concrete technical detail over vague enthusiasm. Use ONLY facts tagged 'verified' in the input JSON as claims of fact. If an 'unverified' fact is present, you may reference it only with explicit hedge language (e.g. 'early numbers suggest', 'not yet independently verified') or omit it entirely - never state it as settled fact. If the input describes team work, attribute it as team work, not solo. Output only the post text, nothing else."
    },
    {
      role: "user",
      content: $json.choices[0].message.content
    }
  ]
}) }}

={{ JSON.stringify({
  model: "openai/gpt-oss-120b",
  max_tokens: 500,
  messages: [
    {
      role: "system",
      content: "You are a strict editor checking a LinkedIn draft against a fact sheet. Flag: (1) any claim in the draft not present in the verified key_facts, (2) any unverified fact stated as settled, (3) hype language (thrilled, excited, game-changing, revolutionary, honored, humbled), (4) solo/team attribution mismatches versus the source facts, (5) voice drift from 'direct, decision-driven, honest about limits, no hype'. Output ONLY valid JSON, no markdown fences: {\"pass\": boolean, \"issues\": [string]}. pass is true only if issues is empty."
    },
    {
      role: "user",
      content: 'FACT SHEET:\n' + $('STEP 2 - Synthesize (Groq call 1)').item.json.choices[0].message.content + '\n\nDRAFT:\n' + $json.choices[0].message.content
    }
  ]
}) }}

={{ JSON.stringify({
  model: "openai/gpt-oss-120b",
  max_tokens: 600,
  messages: [
    {
      role: "system",
      content: "Revise the LinkedIn draft to fix every issue listed. Keep the voice: direct, decision-driven, honest about limits, no hype. Output only the revised post text, nothing else."
    },
    {
      role: "user",
      content: 'DRAFT:\n' + $('STEP 3 - Draft (Groq call 2)').item.json.choices[0].message.content + '\n\nISSUES TO FIX:\n' + JSON.stringify(JSON.parse($json.choices[0].message.content).issues)
    }
  ]
}) }}
